import json, re
from pathlib import Path

num_re = re.compile(r"-?\d[\d,]*(?:\.\d+)?|\.\d+")

def nums(s):
    out=[]
    for t in num_re.findall(s):
        try:
            out.append(float(t.replace(",","")))
        except:
            pass
    return out

def eq(a,b):
    return abs(a-b)<1e-4

def load(p):
    rows=[]
    with open(p) as f:
        for line in f:
            if line.strip():
                rows.append(json.loads(line))
    return rows

def analyze(path, label):
    rows=load(path)
    n=len(rows)
    # positions of gold number relative to end
    last_ok=0
    in_last_300=0
    in_last_100=0
    anywhere=0
    gold_only_before_300=0
    # if multiple gold occurrences, where is the last gold
    last_gold_char_from_end=[]
    # reward would use last number in last 300
    rew_last300=0
    rew_full=0
    # boxed last
    boxed_ok=0
    has_boxed=0
    for r in rows:
        out=r["output"]
        try:
            gt=float(str(r["gts"]).replace(",",""))
        except:
            continue
        ns=nums(out)
        if any(eq(x,gt) for x in ns):
            anywhere+=1
            # last index of gold as substring numerically is harder; char position of last matching number
            matches=list(num_re.finditer(out))
            last_pos=None
            for m in matches:
                try:
                    v=float(m.group().replace(",",""))
                except:
                    continue
                if eq(v,gt):
                    last_pos=m.end()
            if last_pos is not None:
                dist=len(out)-last_pos
                last_gold_char_from_end.append(dist)
                if dist<=300:
                    in_last_300+=1
                else:
                    gold_only_before_300+=1
                if dist<=100:
                    in_last_100+=1
        tail=out[-300:]
        ntail=nums(tail)
        nfull=ns
        if ntail and eq(ntail[-1], gt):
            rew_last300+=1
        if nfull and eq(nfull[-1], gt):
            rew_full+=1
            last_ok+=1
        if "boxed" in out or "\\boxed" in out:
            has_boxed+=1
    print(f"{label}: n={n} last_num_ok={last_ok/n:.3f} last300_lastnum_ok={rew_last300/n:.3f} "
          f"gold_anywhere={anywhere/n:.3f} gold_in_last300={in_last_300/n:.3f} "
          f"gold_only_before_300={gold_only_before_300/n:.3f} gold_in_last100={in_last_100/n:.3f} boxed={has_boxed}")
    if last_gold_char_from_end:
        s=sorted(last_gold_char_from_end)
        print(f"  last gold dist-from-end p50={s[len(s)//2]} p90={s[int(len(s)*0.9)]} max={s[-1]} mean={sum(s)/len(s):.0f}")

base=Path("/workspace/results/run60")
for step in [0,10,20,30,40,50,60]:
    analyze(base/f"val_generations/{step}.jsonl", f"val {step}")
print("---")
for step in [1,10,20,30,40,50,60]:
    analyze(base/f"rollouts/{step}.jsonl", f"roll {step}")
