    try:
        return float(t)
    except:
        return None

def gold_num(g):
    t=str(g).replace(",","").replace("$","")
    try:
        return float(t)
    except:
        return None

def string_last_flex(s, clip=300):
    t=s
    if len(t)>clip:
        t=t[-clip:]
    ans=re.findall(r"(\-?[0-9\.\,]+)", t)
    if not ans:
        return None
    for a in reversed(ans):
        if a not in ("","."):
